"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': "The Grumble King's Curse", 'author': 'Signature original', 'genre': 'Moonlit Meadows', 'chapters': [{'n': 1, 'title': 'The Finding', 'text': "Ember found a silver acorn on the first day of spring, under the oldest oak in the Moonlit Meadow, where the fireflies danced like sparks. It glowed. Things that glow, Ember's grandmother always said, are either magic or trouble. Often both.\n\na talking fox appeared as if called — perhaps by the glow, perhaps by fate. 'That's a silver acorn,' a talking fox said, eyes wide. 'The stories say it chooses someone. It seems it chose you.'\n\nThey set out at dawn, a silver acorn in Ember's pocket, a talking fox at their side. the Moonlit Meadow held its breath. be brave, be kind — Ember didn't know it yet, but they were about to prove it."}, {'n': 2, 'title': 'The Journey', 'text': "They met the wise owl at the crossroads, who asked a riddle: 'What grows when shared?' Ember answered, 'be brave, be kind — I mean, kindness!' The owl hooted approval and gave them a feather for the road.\n\nThey escaped by starlight-light, laughing and shaking. a silver acorn glowed brighter, as if proud. Ember was starting to understand: it wasn't just a magical object. It was a friend, too.\n\nAt the edge of the Moonlit Meadow, they looked back at the darkened woods and forward at the Grumble King's thorn castle. 'Together?' Ember asked. 'Always,' said a talking fox. And in they went."}, {'n': 3, 'title': 'The Thorn Castle', 'text': "Inside, everything was grey: grey tapestries, grey servants, a grey throne where the Grumble King sat, holding the stolen starlight of the Moonlit Meadow in a jar. 'Mine,' the Grumble King hissed. 'All mine.'\n\nThe battle was strange and wonderful: a silver acorn's light against the Grumble King's dark, Ember's courage against the Grumble King's spite, a talking fox's loyalty against everything. Light, it turns out, is very stubborn.\n\nthe Grumble King's castle was made of thorns and sulks. The door asked for a password. a talking fox guessed 'please' — and it worked, because manners are magic the Grumble King never learned."}, {'n': 4, 'title': 'Starlight Restored', 'text': "They carried the starlight home to the Moonlit Meadow in a silver acorn, which had grown to hold it all. The brook ran forward again. The mushrooms glowed gold. The stars came back, one by one, like friends returning.\n\na silver acorn chose to stay with Ember — or Ember chose to stay with it; by now they weren't sure there was a difference. It sits by the bed, glowing softly, a nightlight of pure story.\n\nthe Moonlit Meadow celebrated: the fireflies spelled Ember's name, the oak dropped acorns of thanks, the wise owl composed a ballad with a talking fox as the hero — a talking fox insisted Ember was the hero; they compromised on both."}, {'n': 5, 'title': 'The Promise Kept', 'text': "a talking fox is older now, greyer, no less brave. They still walk together, still argue about the ballad, still keep the grumble-jar dusted. Friendship, like starlight, doesn't fade if you tend it.\n\nNew children come to hear the story, and Ember tells it true: the fear, the laughter, the moment it almost went wrong. 'Were you scared?' they ask. 'Terrified,' Ember says. 'That's what brave is.'\n\nbe brave, be kind. In the Moonlit Meadow, in the starlight, in every heart that hears the tale: the promise kept, the story told, the magic real."}, {'n': 6, 'title': 'Bedtime', 'text': "Sleep tight, the Moonlit Meadow. The dark is just the blanket. The light is a silver acorn, and a silver acorn is here, and Ember is here, and a talking fox is here.\n\nbe brave, be kind. Goodnight.\n\n'Again,' says the listener. It is always 'again.' The best stories are."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

